// Error output of the LLM chain. If every account failed, the API is down or out of credit: raise a real error so M1 fires the watchdog.
const items = $input.all();
if (!items.length) return [];
const first = items[0].json || {};
const msg = String(first.error || 'model call failed');
return [{ json: { failed: items.length, message: msg } }];
